  const installed = result.status === 0 ? String(result.stdout).trim().split(/\s+/u).slice(1) : [];
  if (installed.length === 0 || installed.some((entry) => entry !== version)) return;

  let tag: string;
  try {
    tag = await withTimeout((signal) => latestTag(signal), UPGRADE_CHECK_TIMEOUT_MS, 'the release check');
  } catch (error) {
    process.stderr.write(`warning: could not confirm the upgrade: ${(error as Error).message}\n`);
    return;
  }
  if (!isNewerRelease(tag, version)) return;
  process.stderr.write(
    `error: ${install.manager} still has ${binaryName} ${version}, but ${tag} is released.\n` +
      `The release may not have reached its tap yet. Try again later, or run:\n  ${install.upgrade}\n`,
  );
  process.exitCode = 1;
