/** Maps this machine onto the release asset built for it, matching the names the release step packs. */
const detectTarget = (): string => {
  const platforms: Record<string, string> = { darwin: 'darwin', linux: 'linux' };
  const architectures: Record<string, string> = { x64: 'x64', arm64: 'arm64' };
  const os = platforms[process.platform];
  const arch = architectures[process.arch];
  if (!os || !arch) {
    throw new Error(`no release binary is published for ${process.platform}/${process.arch}`);
  }
  return `${os}-${arch}`;
};

/** Latest published release tag, read from the GitHub API so the command can report the version. */
const latestTag = async (signal?: AbortSignal): Promise<string> => {
  const response = await fetch(`https://api.github.com/repos/${RELEASE.repo}/releases/latest`, {
    // `connection: close` because the abort below bounds the *request*, not the process. Node keeps
    // a pooled keep-alive socket referenced after the response resolves, so an unawaited check still
    // held the process open for seconds after the command's own work finished — the delay this is
    // supposed to have no part in. Bun does not exhibit it; the npm channel runs on Node.
    headers: { accept: 'application/vnd.github+json', connection: 'close' },
    ...(signal ? { signal } : {}),
  });
  if (!response.ok) {
    // An unauthenticated read past GitHub's per-address limit is refused with 403 or 429, not with the
    // release missing. Said as such, because the status alone reads like a broken release.
    if (response.status === 403 || response.status === 429) {
      throw new Error(
        `GitHub refused the release lookup (HTTP ${response.status}), usually the unauthenticated API rate limit for this network; try again later`,
      );
    }
    throw new Error(`could not read the latest release (HTTP ${response.status})`);
  }
  // Capped like the archive read is. A release payload is a few kilobytes of JSON, and this is the
  // request the *daily notifier* makes unasked — so a redirect or captive proxy answering with an
  // endless body inside the deadline would buffer it into a CLI the user only ran to do something
  // else. `json()` offers no way to bound it, so the bytes are read first and parsed after.
  const body = JSON.parse(
    (await readCapped(response, response.url || 'the latest release', MAX_METADATA_BYTES)).toString('utf8'),
  ) as { tag_name?: unknown };
  if (typeof body.tag_name !== 'string' || body.tag_name.length === 0) {
    throw new Error('the latest release has no tag');
  }
  // Validated here, not only where a *cached* tag is printed. This value goes straight into a download
  // URL and onto the terminal, and the same reasoning applies to both paths: a git refname cannot hold
  // a control character, so one that does was not written by a release — and writing it raw would let
  // cursor-control sequences rewrite the surrounding lines and forge an instruction that appears to
  // come from the CLI itself. Checking the cache and trusting the live response left the guard on the
  // path that had already been through it and off the path the value arrives by.
  if (!RELEASE_TAG.test(body.tag_name)) {
    throw new Error('the latest release has an unusable tag');
  }
  return body.tag_name;
};

/**
 * Fetches one release asset, bounded by both a deadline and a size cap.
 *
 * Used for the archive and for `checksums.txt`, so both halves of the integrity check are bounded the
 * same way — a release that answers one of them slowly cannot leave the command waiting indefinitely.
 */
const download = async (url: string): Promise<Buffer> =>
  // The *whole* read runs inside the deadline, headers and body alike. Bounding only the `fetch` call
  // leaves the body unbounded: a proxy that answers 200 and then stops sending bytes resolves the
  // response, the timer is cleared, and the command hangs forever on the read — the exact failure
  // this exists to prevent, one step later than where it was first looked for.
  withTimeout(
    async (signal) => {
      const response = await fetch(url, { signal });
      if (!response.ok) throw new Error(`could not download ${url} (HTTP ${response.status})`);
      return readCapped(response, url);
    },
    DOWNLOAD_TIMEOUT_MS,
    url,
  );

/**
 * Reads a response body, refusing one larger than {@link MAX_DOWNLOAD_BYTES}.
 *
 * Read chunk by chunk with a running total rather than through `arrayBuffer()`: that buffers the
 * whole body *before* any length can be checked, so a cap applied afterwards has already paid the
 * memory it was meant to refuse. `content-length` is checked first where the server sends one,
 * because that refuses the transfer before a byte of it arrives — but it is a claim, not a
 * guarantee, so the running total is what actually enforces the bound.
 *
 * Buffered whole once read, because the checksum is over the whole archive. A compiled executable
 * for one platform is tens of megabytes, so the cap is loose enough never to reject a real asset.
 */
const readCapped = async (response: Response, url: string, limit = MAX_DOWNLOAD_BYTES): Promise<Buffer> => {
  // Reported in megabytes against whichever limit is in force, since both are whole megabytes. A unit
  // switch would be dead code today; add one here if a sub-megabyte cap is ever introduced.
  /** The refusal, named once because the declared length and the running total both raise it. */
  const tooLarge = (): Error =>
    new Error(`${url} is larger than the ${Math.round(limit / 1_000_000)}MB limit`);

  const declared = Number(response.headers.get('content-length') ?? '');
  if (Number.isFinite(declared) && declared > limit) throw tooLarge();

  // No body to stream (a HEAD-like response, or a stub in a test) leaves `arrayBuffer` as the only
  // reader; it is bounded by the same cap on the way out.
  if (!response.body) {
    const whole = Buffer.from(await response.arrayBuffer());
    if (whole.byteLength > limit) throw tooLarge();
    return whole;
  }

  const chunks: Buffer[] = [];
  let total = 0;
  const reader = response.body.getReader();
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    if (total > limit) {
      // Released so the connection is torn down rather than left draining in the background.
      await reader.cancel().catch(() => {});
      throw tooLarge();
    }
    chunks.push(Buffer.from(value));
  }
  return Buffer.concat(chunks);
};

/** Upper bound on a release asset, so a wrong URL cannot buffer an unbounded body into memory. */
const MAX_DOWNLOAD_BYTES = 250_000_000;

/**
 * Upper bound on an API read, which is the release JSON and nothing else.
 *
 * Far tighter than the asset cap because the shape is known: a `releases/latest` payload is a few
 * kilobytes, and generous room for release notes still leaves this three orders of magnitude below
 * the archive bound. This is the request the daily check makes without being asked, so it is the one
 * that most needs a bound the user never has to think about.
 */
const MAX_METADATA_BYTES = 2_000_000;

/** How long the downloaded executable may take to answer `--version` before it counts as broken. */
const VERSION_PROBE_TIMEOUT_MS = 15_000;

/** Long enough for a large archive on a slow connection, short enough to fail rather than hang. */
const DOWNLOAD_TIMEOUT_MS = 120_000;

/** How long `upgrade` waits on the release API before giving up; it is interactive, so it is short. */
const UPGRADE_CHECK_TIMEOUT_MS = 10_000;

/**
 * Runs one request under a deadline, so a stalled connection fails instead of hanging.
 *
 * `fetch` has no default timeout, and a captive portal or a stalled proxy completes the handshake
 * and then never answers — which left `upgrade` sitting with nothing on screen, indefinitely, while
 * the daily notifier on the same machine aborted after two seconds. `.agents/security.md` asks for
 * every request a generated runtime makes to be bounded.
 */
const withTimeout = async <T>(
  run: (signal: AbortSignal) => Promise<T>,
  ms: number,
  what: string,
): Promise<T> => {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  try {
    return await run(controller.signal);
  } catch (error) {
    // `AbortError` names the signal, not the cause, so it is reported as what the user experienced.
    if (controller.signal.aborted) throw new Error(`${what} timed out after ${Math.round(ms / 1000)}s`);
    throw error;
  } finally {
    clearTimeout(timer);
  }
};

/**
 * Replaces this executable with the one from `tag`, verified against the release's checksums.
 *
 * The integrity check the release's own `checksums.txt` exists for, with bounds on both reads: the archive and
 * the checksum file come from one release, so this catches a corrupted or truncated download rather
 * than a compromised release.
 */
const replaceExecutable = async (executable: string, tag: string, binaryName: string): Promise<void> => {
  const asset = `${binaryName}-${detectTarget()}.tar.gz`;
  const base = `https://github.com/${RELEASE.repo}/releases/download/${tag}`;

  const archive = await download(`${base}/${asset}`);
  const checksums = (await download(`${base}/checksums.txt`)).toString('utf8');
  // Same two-field `sha256sum` format the release publishes: "<hash>  <file>".
  const expected = checksums
    .split('\n')
    .map((line) => line.trim().split(/\s+/u))
    .find((fields) => fields[1] === asset)?.[0];
  if (!expected) throw new Error(`the release publishes no checksum for ${asset}`);
  const actual = createHash('sha256').update(archive).digest('hex');
  if (actual !== expected.toLowerCase()) {
    throw new Error(`checksum mismatch for ${asset} (expected ${expected}, got ${actual})`);
  }

  const staging = mkdtempSync(join(tmpdir(), `${binaryName}-upgrade-`));
  // Written beside the target rather than in the temp dir, so the final rename is within one
  // filesystem and therefore atomic — a cross-device rename would fall back to a copy that can be
  // interrupted halfway, leaving a truncated executable on the user's PATH.
  const pending = join(dirname(executable), `.${binaryName}.upgrade`);
  try {
    const archivePath = join(staging, asset);
    writeFileSync(archivePath, archive);
    // `tar` is present on every platform this upgrades on (macOS and Linux); Windows self-upgrades
    // are unreachable because its asset is a `.zip` no release publishes a `.tar.gz` for.
    //
    // The child's PATH is pinned, and resolving `tar` absolutely is not enough on its own: GNU tar
    // implements `-z` by *running* `gzip`, looked up through the inherited PATH (verified against GNU
    // tar 1.35). Under `sudo` on a system whose sudoers has no `secure_path` — several distributions
    // ship none — the user's own `gzip` would then run as root, which is the hole pinning `tar` was
    // meant to close, one process along. bsdtar on macOS decompresses in-process and never looks.
    // The rest of the environment is passed through, so locale and proxy settings still apply.
    execFileSync(tarProgram(), ['-xzf', archivePath, '-C', staging], {
      env: { ...process.env, PATH: TRUSTED_TOOL_PATH },
    });
    const extracted = join(staging, binaryName);
    // The archive layout is a release-time contract this cannot verify ahead of time, and a bare
    // ENOENT from the read below matches none of the guidance `upgrade` prints, so it is checked
    // here, naming the archive rather than letting a bare ENOENT surface from the read below.
    if (!existsSync(extracted)) {
      throw new Error(`${asset} did not contain the expected ${binaryName} executable`);
    }

    // `wx` rather than a plain write: the path is a fixed, predictable name in the directory the real
    // executable lives in, and this command tells the user to re-run it under `sudo`. A plain
    // `writeFileSync` follows a symlink, so anyone who can create that one name in a group-writable
    // install directory chooses a file for root to overwrite with content they also control. `wx` is
    // `O_CREAT|O_EXCL`, which refuses an existing file and a symlink alike, so the only way past it is
    // a live race rather than a planted link.
    //
    // Unlinked first, because `wx` refuses a *stale* file too. The `finally` below cleans up after this
    // process, but a run killed outright — SIGKILL, OOM, power loss — leaves the name behind with no
    // cleanup having run, and the next `upgrade` would then fail with a bare `EEXIST` naming a hidden
    // dotfile the user has no reason to know about. That message matches none of the guidance this
    // command prints. Removing the link rather than following it keeps the property: a name re-created
    // between these two lines makes the write fail, which is the right outcome.
    rmSync(pending, { force: true });
    writeFileSync(pending, readFileSync(extracted), { flag: 'wx' });
    chmodSync(pending, 0o755);

    // Run before it replaces anything, exactly as `install.sh` does. The checksum proves the archive
    // is the one the release published; it says nothing about whether this machine can execute what
    // came out of it — a 32-bit userland on a 64-bit kernel reports a 64-bit `uname -m`, and a release
    // can simply be built wrong. Replacing the working binary with one that cannot run takes `upgrade`
    // with it, so the tool that would recover the install is the one just broken. Failing here leaves
    // the old executable in place, and the `finally` below removes the staged file.
    //
    // The staged path is absolute and `execFileSync` takes no shell, so nothing here is interpreted.
    // Output is discarded: this asks whether the binary runs, not what it says. The environment is the
    // real one, not the pinned `PATH` the extraction uses — that pin exists because `tar` resolves
    // `gzip` through it, while this runs a known absolute path, and stripping the environment would
    // only risk failing a build that runs perfectly well in the one it is about to be installed into.
    // Bounded, because a build that hangs instead of failing would otherwise hang `upgrade` with it.
    // `--version` is answered by the program before any command runs and makes no request — the
    // update check skips it — so a working build is done in well under a second.
    try {
      execFileSync(pending, ['--version'], {
        stdio: 'ignore',
        timeout: VERSION_PROBE_TIMEOUT_MS,
        killSignal: 'SIGKILL',
      });
    } catch (error) {
      const hung = (error as NodeJS.ErrnoException).code === 'ETIMEDOUT';
      throw new Error(
        hung
          ? `the downloaded ${binaryName} did not answer --version within ${VERSION_PROBE_TIMEOUT_MS / 1000}s; nothing was changed`
          : `the downloaded ${binaryName} does not run on this machine (${process.platform} ${process.arch}); nothing was changed`,
      );
    }

    // Replacing a running executable is legal on POSIX: the running process keeps the old inode
    // open, and the next invocation resolves the new one.
    renameSync(pending, executable);
  } finally {
    rmSync(staging, { recursive: true, force: true });
    // A failure between the write and the rename — ENOSPC, a signal — would otherwise leave a
    // partial dotfile next to the real executable, owned by root in the `sudo upgrade` flow this
    // command tells the user to run.
    rmSync(pending, { force: true });
  }
};

/**
 * The directories a trusted system tool is looked up in, and the `PATH` the extraction runs with.
 *
 * Both uses need the same answer, so they share one value: `tar` is resolved from here rather than
 * through the caller's `PATH`, and the child is given this as its `PATH` because GNU tar implements
 * `-z` by running `gzip`, which it finds the ordinary way. These two cover macOS and every mainstream
 * Linux distribution; an image that keeps `tar` elsewhere is handled by the ownership-checked search
 * below instead of by widening this.
 */
const TRUSTED_TOOL_PATH = '/usr/bin:/bin';

/**
 * Absolute path to `tar`, so the extraction cannot be redirected by `PATH`.
 *
 * `upgrade` tells the user to re-run under `sudo` when the executable is not writable, and macOS
 * ships no `secure_path` in its default sudoers — so a bare `tar` would resolve through the invoking
 * user's `PATH` and run a file they control as root. The two standard locations are tried first
 * because they cover macOS and every mainstream Linux distribution.
 *
 * The `PATH` search that follows is for the images that keep `tar` elsewhere (`/usr/local/bin` under
 * Nix or Homebrew-on-Linux). Absolute entries alone are not enough — `/tmp/evil` is absolute — so a
 * candidate is accepted only if root owns it and no one else can write it or the directory holding
 * it. That is the property that matters under `sudo`, and it is what a store path or a distribution
 * prefix has while an attacker-controlled directory does not. Nothing found means an outright
 * failure: there is no safe way to run a program this cannot locate.
 */
const tarProgram = (): string => {
  for (const candidate of TRUSTED_TOOL_PATH.split(':').map((directory) => `${directory}/tar`)) {
    if (existsSync(candidate)) return candidate;
  }
  for (const entry of (process.env['PATH'] ?? '').split(':')) {
    if (!entry.startsWith('/')) continue;
    const candidate = join(entry, 'tar');
    if (existsSync(candidate) && rootOwnedAndProtected(candidate) && rootOwnedAndProtected(entry))
      return candidate;
  }
  throw new Error('no trusted tar was found on PATH, so the archive cannot be extracted');
};

/** Whether root owns the path and neither group nor other can write it — checked without following links. */
const rootOwnedAndProtected = (path: string): boolean => {
  try {
    const stats = lstatSync(path);
    return stats.uid === 0 && (stats.mode & 0o022) === 0;
  } catch {
    return false;
  }
};

/**
 * Whether `tag` names a release newer than the running `version`.
 *
 * "Different" is not "newer". `releases/latest` follows whatever release is currently marked latest,
 * so deleting a broken release moves it *backwards* — and a bare inequality would then tell a user
 * on 2.0.1 that "a new release is available: 2.0.1 → v2.0.0". Release-please, which every generated
 * CLI publishes through, produces strict semver, so that is what is compared; anything else falls
 * back to the inequality, on the grounds that an imprecise word beats never mentioning a release at
 * all for a versioning scheme this cannot read.
 */
const isNewerRelease = (tag: string, version: string): boolean => {
  const candidate = tag.replace(/^v/u, '');
  const latest = parseVersion(candidate);
  const current = parseVersion(version);
  if (!latest || !current) return candidate !== version;

  for (let index = 0; index < latest.release.length; index += 1) {
    const next = latest.release[index] ?? 0;
    const now = current.release[index] ?? 0;
    if (next !== now) return next > now;
  }
  // Same `major.minor.patch`: semver puts a prerelease below the release it leads to, so `1.2.0` is
  // newer than `1.2.0-rc.1`.
  if (latest.prerelease === current.prerelease) return false;
  if (!latest.prerelease) return true;
  if (!current.prerelease) return false;
  return comparePrerelease(latest.prerelease, current.prerelease) > 0;
};

/**
 * Orders two semver prerelease strings, returning >0 when `left` is the newer one.
 *
 * Semver's dotted rule, not a string comparison: identifiers are compared field by field, numeric
 * ones numerically and the rest lexically, with numeric sorting below alphanumeric and a shorter
 * prefix below its extension. Comparing the whole string instead put `rc.10` *below* `rc.9`, which a
 * long prerelease train reaches routinely — a user on `rc.9` would then never be told about `rc.10`,
 * and running `upgrade` would install it while calling the result a move rather than an upgrade.
 */
const comparePrerelease = (left: string, right: string): number => {
  const a = left.split('.');
  const b = right.split('.');
  for (let index = 0; index < Math.max(a.length, b.length); index += 1) {
    const x = a[index];
    const y = b[index];
    // A field the other side does not have makes the longer one greater, per semver.
    if (x === undefined) return -1;
    if (y === undefined) return 1;
    if (x === y) continue;
    const xNumeric = /^\d+$/u.test(x);
    const yNumeric = /^\d+$/u.test(y);
    if (xNumeric && yNumeric) return Number(x) - Number(y);
    // Numeric identifiers always sort below alphanumeric ones.
    if (xNumeric !== yNumeric) return xNumeric ? -1 : 1;
    return x < y ? -1 : 1;
  }
  return 0;
};

/** Splits a strict semver string into its numeric release triple and prerelease text, or undefined. */
const parseVersion = (value: string): { release: readonly number[]; prerelease: string } | undefined => {
  const match = /^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?$/u.exec(value);
  if (!match) return undefined;
  return { release: [Number(match[1]), Number(match[2]), Number(match[3])], prerelease: match[4] ?? '' };
};

/**
 * This command's own opt-out variable, fixed at generation time.
 *
 * Substituted rather than derived from `binaryName` here, because the generated README documents it
 * by name — deriving it twice is how a documented opt-out stops matching the one that is read.
 */
const UPDATE_OPT_OUT = 'DEDALUS_NO_UPDATE_NOTIFIER';

/** Charset a git tag can actually use, applied to anything read back from the cache before printing. */
const RELEASE_TAG = /^[A-Za-z0-9._+-]{1,64}$/u;

/** How long a version check is trusted before the next run looks again. */
const CHECK_INTERVAL_MS = 24 * 60 * 60 * 1000;

/**
 * Hard bound on the background version check.
 *
 * `fetch` keeps its socket referenced, so an unawaited request still holds the process open after
 * the command's own work is done — a host that accepts the connection and never answers (a captive
 * portal, a stalled proxy) would otherwise hang the CLI indefinitely on every run. The abort caps
 * that at this, and the cache write below caps how often it can happen at all.
 */
const CHECK_TIMEOUT_MS = 2_000;

/** One line naming the installed and available versions, shared by `upgrade` and `upgrade --check`. */
const versionLine = (binaryName: string, version: string, tag: string): string =>
  `${binaryName} ${version} is installed; ${tag} is available.\n`;

/** Resolves the latest tag, reporting and setting a failing exit code rather than throwing. */
const resolveLatestTag = async (): Promise<string | undefined> => {
  try {
    return await withTimeout((signal) => latestTag(signal), UPGRADE_CHECK_TIMEOUT_MS, 'the release check');
  } catch (error) {
    process.stderr.write(`error: ${(error as Error).message}\n`);
    process.exitCode = 1;
    return undefined;
  }
};

/** Where the last check is remembered, so every invocation does not hit the network. */
const cachePath = (binaryName: string): string | undefined => {
  // Windows sets neither `HOME` nor `XDG_CACHE_HOME` from cmd or PowerShell, so without this the
  // cache lands under the temp directory that Disk Cleanup purges — and the throttle it exists to
  // enforce would reset every time that happened.
  if (process.platform === 'win32') {
    const local = process.env['LOCALAPPDATA'];
    return local ? join(local, binaryName, 'update-check.json') : undefined;
  }
  // A relative `XDG_CACHE_HOME` is invalid per the XDG base directory spec and ignored, which also
  // keeps the cache off a path that would otherwise be resolved against the working directory: the
  // throttle would then be per-directory, and a repository could carry a writable one.
  const xdg = process.env['XDG_CACHE_HOME'];
  const base = (xdg && isAbsolute(xdg) ? xdg : undefined) ?? homeCacheBase();
  return base ? join(base, binaryName, 'update-check.json') : undefined;
};

/** Per-user cache root under `$HOME`, or undefined when there is no home directory to put it in. */
const homeCacheBase = (): string | undefined => {
  const home = process.env['HOME'];
  if (!home) return undefined;
  return process.platform === 'darwin' ? join(home, 'Library', 'Caches') : join(home, '.cache');
};

/**
 * Whether it is safe to print an update hint at all.
 *
 * Deliberately conservative. The notice is a courtesy, and every case below is one where printing it
 * does more harm than the notice is worth:
 *
 * - Not a TTY on stderr: the output is being captured or piped, where an unexpected line is noise at
 *   best and corrupts a parsed stream at worst. This is also why the notice only ever goes to
 *   stderr — stdout carries the command's real output, which `--format json` callers parse.
 * - `CI`: build logs are read by machines and by people debugging failures, neither of whom asked.
 * - `NO_UPDATE_NOTIFIER` or this command's own opt-out variable: an explicit request to stop.
 */
const notificationsAllowed = (): boolean => {
  if (process.env['CI']) return false;
  if (process.env['NO_UPDATE_NOTIFIER']) return false;
  if (process.env[UPDATE_OPT_OUT]) return false;
  // Never under `sudo`, and the reason is the throttle rather than the notice. `sudo` keeps `HOME` on
  // macOS, so a root run that lands past the 24h window creates the cache directory owned by root —
  // and every later run as the real user then fails to write it, silently. With nothing recorded the
  // throttle never engages, so the unauthenticated API request goes out on *every* invocation, which
  // is exactly the rate-limit exhaustion recording-before-the-request exists to prevent. `upgrade`
  // itself tells the user to re-run under `sudo` for a root-owned install, so this is a path they are
  // actively sent down.
  //
  // Keyed on `SUDO_USER` rather than on being root, deliberately. `SUDO_USER` is set only where sudo
  // elevated from a real user — precisely when `HOME` belongs to somebody else — while plain root
  // (a container image, a root-only appliance) owns its own `$HOME` and has no such problem. Testing
  // `getuid() === 0` would switch the notice off for every containerized CLI, which is a large class
  // of ordinary user, to fix a case they are not in.
  if (process.env['SUDO_USER']) return false;
  // Both streams, not just stderr. The documented way to install completions is
  // `eval "$(<bin> completion bash)"` in a shell rc: that captures stdout while leaving stderr
  // attached to the terminal, so a stderr-only gate printed the notice into *every new shell* the
  // user opened. Requiring stdout to be a terminal too is what tells a real interactive run from a
  // command whose output something else is reading.
  return Boolean(process.stderr.isTTY) && Boolean(process.stdout.isTTY);
};

/**
 * Tells the user, at most once a day, that a newer release exists.
 *
 * Fire-and-forget on purpose: it is started before the command runs and never awaited, so a slow or
 * unreachable network never delays the command's own work. The process can still be held open for up
 * to {@link CHECK_TIMEOUT_MS} after it finishes, on a stalled connection, at most once a day. Every failure path is silent — a version check that cannot
 * reach GitHub is not something the user asked about, and reporting it would turn a courtesy into
 * noise on every offline run.
 *
 * The notice is printed on the *next* run rather than this one when the cache is cold: the check
 * resolves after the command has usually finished, and interleaving a notice with output already in
 * flight is worse than telling them a moment later.
 */
export const notifyIfOutdated = (
  binaryName: string,
  version: string,
  argv: readonly string[] = process.argv,
): void => {
  if (!notificationsAllowed()) return;
  // Commander answers these and exits before a request could leave the process, but only after the
  // attempt below is recorded — so the day's first `--help` would use up the day's check without
  // making it. Skipped instead, which keeps the throttle and the check.
  if (answeredWithoutRunning(argv.slice(2))) return;

  // No private cache directory means no throttle, and an unthrottled check would hit the API on
  // every invocation. It also means the only remaining location would be a world-writable one:
  // with `HOME` unset (`su` without `-`, `env -i`, a minimal container) a `/tmp/<command>/` fallback
  // is a path any local user can create first and then own, and its contents are written to this
  // terminal below. Skipping the check entirely is the cheap, safe answer.
  const path = cachePath(binaryName);
  if (!path) return;

  let cached: { checkedAt?: number; latest?: string } = {};
  try {
    const parsed: unknown = JSON.parse(readFileSync(path, 'utf8'));
    // `JSON.parse` returns `null` for the literal `null` without throwing, and `typeof null` is
    // `'object'` — so both are checked. Reading `.latest` off `null` would throw *outside* this
    // catch, and the notifier runs while the program is being built, taking the whole CLI down with
    // an unhandled stack trace on every invocation until the file is deleted by hand.
    if (parsed && typeof parsed === 'object') cached = parsed as typeof cached;
  } catch {
    // No cache yet, or an unreadable one: treated as "never checked".
  }

  // Report what the last check found before starting another, so a known-stale version is surfaced
  // immediately rather than a day later.
  // Validated before it reaches the terminal. A real `tag_name` cannot contain control characters —
  // git refnames forbid them — so anything that does was not written by this code, and writing it
  // raw would let cursor-control sequences rewrite the surrounding lines and forge an instruction
  // that appears to come from the CLI itself.
  if (cached.latest && RELEASE_TAG.test(cached.latest) && isNewerRelease(cached.latest, version)) {
    const install = detectInstall(binaryName);
    // `<bin> upgrade` wherever it can do the work itself — in place, or by running the owning manager
    // — and the manager's own instruction only where it can do neither.
    const how = install.kind === 'managed' && !install.run ? install.upgrade : `${binaryName} upgrade`;
    process.stderr.write(
      `\nA new release of ${binaryName} is available: ${version} → ${cached.latest}\n  ${how}\n\n`,
    );
  }

  // A negative delta satisfies a bare `<`, so a `checkedAt` written while the clock was ahead — a
  // dead RTC battery, a hypervisor clock jump on resume — would suppress every later check for the
  // whole skew and the user would never hear about another release. Out-of-range in either direction
  // means "check again".
  const since = Date.now() - (cached.checkedAt ?? 0);
  if (cached.checkedAt && since >= 0 && since < CHECK_INTERVAL_MS) return;

  // The attempt is recorded *before* the request, not when it resolves. Commander exits the process
  // outright for `--help`, `--version` and any usage error, which kills the in-flight check before
  // it can write anything — so a user who mostly types `--help` would issue one unauthenticated API
  // request per invocation forever, never cache a result, and eventually exhaust GitHub's 60/hr
  // limit for their whole NAT. Writing up front costs one stale-by-a-day notice at worst.
  recordCheck(path, cached.latest);

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), CHECK_TIMEOUT_MS);
  // The timer itself would hold the event loop open for its full duration; `unref` exists on Node
  // and Bun timers but not in the DOM typing, hence the guarded call.
  (timeout as unknown as { unref?: () => void }).unref?.();

  void latestTag(controller.signal)
    .then((tag) => recordCheck(path, tag))
    // Failure needs no second write: the attempt was already recorded above, so the throttle holds
    // whether the check succeeded, failed, or never finished.
    .catch(() => {})
    .finally(() => clearTimeout(timeout));
};

/**
 * Whether Commander answers these arguments itself — help or the version — and exits without running
 * a command: no arguments at all (the program prints its help), `help`, `-v`/`--version` on their own,
 * or `-h`/`--help` anywhere before a `--` that ends option parsing.
 */
const answeredWithoutRunning = (args: readonly string[]): boolean => {
  const options = args.includes('--') ? args.slice(0, args.indexOf('--')) : args;
  if (options.length === 0 || options[0] === 'help') return true;
  if (options.length === 1 && (options[0] === '-v' || options[0] === '--version')) return true;
  return options.includes('-h') || options.includes('--help');
};

/** Remembers when the check last ran, and what it found, so the throttle above can engage. */
const recordCheck = (path: string, latest: string | undefined): void => {
  try {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, JSON.stringify({ checkedAt: Date.now(), ...(latest ? { latest } : {}) }));
  } catch {
    // An unwritable cache directory is not worth reporting: the check is a courtesy, and the only
    // consequence is that it runs again next time.
  }
};

/**
 * Reports `upgrade --check`: already the latest, a newer release and the command that installs it, or
 * a latest release older than this one.
 *
 * "Different" is not "newer" — `releases/latest` moves backwards when a broken release is deleted — so
 * the ordering decides the wording. `canMove` says whether `how` would install an older release: true
 * for a self-managed install, which `upgrade` replaces with whatever is latest; false for a managed
 * one, whose manager never downgrades.
 */
const reportCheck = (
  binaryName: string,
  version: string,
  tag: string,
  how: string,
  canMove: boolean,
): void => {
  if (tag.replace(/^v/u, '') === version) {
    process.stderr.write(`${binaryName} ${version} is already the latest release.\n`);
    return;
  }
  process.stderr.write(versionLine(binaryName, version, tag));
  if (isNewerRelease(tag, version)) {
    process.stderr.write(`Upgrade it with:\n  ${how}\n`);
    return;
  }
  process.stderr.write(
    canMove
      ? `That is older than what you have. Move to it with:\n  ${how}\n`
      : 'That is older than what you have, so there is nothing to upgrade.\n',
  );
};

/** Whether this process can create and rename files in `directory`. */
const writableDirectory = (directory: string): boolean => {
  try {
    accessSync(directory, constants.W_OK);
    return true;
  } catch {
    return false;
  }
};

/**
 * Registers `upgrade` and `uninstall`, which both hinge on how this executable was installed.
 *
 * `upgrade` upgrades every install it can identify, but never by writing over a file another package
 * manager owns. Overwriting a Homebrew- or npm-managed binary in place leaves that manager's database
 * describing a file that is no longer there: `brew` still reports the old version, and the next managed
 * upgrade silently reverts this one. So a managed install is upgraded by *running* its manager's own
 * command, and only a download nothing else manages is replaced in place. A binary in `/usr/bin` is
 * refused outright, because nothing published here installs there — so something else owns it, and
 * this cannot name what.
 */
export const addUpgradeCommands = (program: Command, binaryName: string, version: string): void => {
  program
    .command('upgrade')
    .description('Upgrade to the latest release')
    .option('--check', 'Report the latest version without installing it')
    .action(async (options: { check?: boolean }) => {
      const install = settledInstall(detectInstall(binaryName));

      // A managed install returns unconditionally, which is also what narrows `install` to the
      // self-managed variant for the replace below — the alternative, testing `kind` again further
      // down, reads as a guard against a state that cannot happen.
      if (install.kind === 'managed') {
        if (options.check) {
          const tag = await resolveLatestTag();
          if (!tag) return;
          process.stderr.write(`${binaryName} was installed with ${install.manager}.\n`);
          // A manager only ever moves forward, so a `releases/latest` that went backwards is nothing
          // to act on here — unlike a self-managed install, which `upgrade` would move to it.
          reportCheck(
            binaryName,
            version,
            tag,
            install.run ? `${binaryName} upgrade` : install.upgrade,
            false,
          );
          return;
        }
        if (install.run) {
          const upgraded = runManagerUpgrade(binaryName, install, install.run);
          if (upgraded && install.run.installedVersions) {
            await confirmManagerUpgrade(
              binaryName,
              version,
              install,
              install.run,
              install.run.installedVersions,
            );
          }
          return;
        }
        process.stderr.write(
          `${binaryName} was installed with ${install.manager}, which owns the installed files.\n` +
            `Upgrade it with:\n  ${install.upgrade}\n`,
        );
        return;
      }

      const tag = await resolveLatestTag();
      if (!tag) return;
      if (options.check) {
        reportCheck(binaryName, version, tag, `${binaryName} upgrade`, true);
        return;
      }

      // Compared as strings after stripping the tag's `v`: the release tag is the package version,
      // so whether to act at all is an equality question, not an ordering one.
      if (tag.replace(/^v/u, '') === version) {
        process.stderr.write(`${binaryName} ${version} is already the latest release.\n`);
        return;
      }

      // Checked before the download rather than discovered at the rename: a root-owned install
      // directory otherwise costs the whole archive before failing with the same permission error.
      if (!writableDirectory(dirname(install.path))) {
        process.stderr.write(
          `error: ${dirname(install.path)} is not writable, so ${install.path} cannot be replaced.\n` +
            `Try again with elevated permissions.\n`,
        );
        process.exitCode = 1;
        return;
      }

      try {
        await replaceExecutable(install.path, tag, binaryName);
        // "moved" rather than "upgraded" when the release moved backwards. `releases/latest` follows
        // whichever release is marked latest, so deleting a broken one really does point this at an
        // older build — installing it is right (that is the release the project is publishing), but
        // calling it an upgrade is not.
        const direction = isNewerRelease(tag, version) ? 'upgraded' : 'moved';
        process.stderr.write(`${direction} ${binaryName} to ${tag}\n`);
      } catch (error) {
        const message = (error as Error).message;
        // A permission error here is the common case — the binary may sit in a root-owned directory —
        // so say what to do rather than only what failed.
        const reinstall = /permission|EACCES|EPERM/iu.test(message)
          ? 'Try again with elevated permissions.\n'
          : '';
        process.stderr.write(`error: ${message}\n${reinstall}`);
        process.exitCode = 1;
      }
    });

  program
    .command('uninstall')
    .description('Show how to remove this installation')
    .action(() => {
      const install = settledInstall(detectInstall(binaryName));
      if (install.kind === 'managed') {
        process.stderr.write(
          `${binaryName} was installed with ${install.manager}, which owns the installed files.\n` +
            `Remove it with:\n  ${install.remove}\n`,
        );
        return;
      }
      // Printed rather than performed: a command that deletes the executable running it cannot
      // report a failure afterwards, and the one-liner is auditable before it is run.
      // Single-quoted, because this is the one line in the module that is a shell command the user is
      // meant to paste. The path comes from `realpathSync(process.execPath)` and can carry spaces —
      // `~/Library/Application Support/...`, or any directory a user named — and an unquoted `rm`
      // would then name two paths, neither of them the executable. Nothing expands inside single
      // quotes, and an embedded `'` is closed, escaped and reopened.
      // `sudo` only where it is needed: a root-owned `/usr/local/bin` refuses a plain `rm`, and a
      // user-owned `~/.local/bin` should not be handed a root command it does not need.
      const sudo = writableDirectory(dirname(install.path)) ? '' : 'sudo ';
      process.stderr.write(
        `Remove ${binaryName} with:\n  ${sudo}rm '${install.path.replace(/'/gu, "'\\''")}'\n${leftoverState(binaryName)}`,
      );
    });
};

/**
 * The state removing the executable leaves behind, named so a user can clear it too.
 *
 * Three things outlive the binary and none is obvious: a stored credential, which `logout` is the
 * right way to clear because only the CLI knows where its keychain entry or file lives — named only
 * when the CLI has sign-in at all — the update-check cache, and the PATH line the install script may
 * have added to a shell startup file, named only when the release ships that script. Printed rather
 * than deleted for the same reason the executable is: `uninstall` reports, so that what it says can be
 * read before it is run.
 */
const leftoverState = (binaryName: string): string => {
  const cache = cachePath(binaryName);
  const leftovers = [
    ...(HAS_LOGIN ? [`  a stored credential, if you signed in — clear it with: ${binaryName} logout\n`] : []),
    ...(cache
      ? [`  the update-check cache — remove it with: rm -rf '${dirname(cache).replace(/'/gu, "'\\''")}'\n`]
      : []),
    ...(HAS_INSTALL_SCRIPT
      ? [
          `  a PATH line, if the install script added one — delete the two lines starting at "# Added by the ${binaryName} installer" in your shell startup file (for fish, the file conf.d/${binaryName}.fish)\n`,
        ]
      : []),
  ];
  return leftovers.length > 0 ? `\nThis leaves no other files behind except:\n${leftovers.join('')}` : '';
};
